(()=>{const TA=window.TASideScroller=window.TASideScroller||{},A={},C={};
const base='assets/runtime/';
function load(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=base+src})}
function cells(im,cols,rows){const out=[],w=im.naturalWidth/cols,h=im.naturalHeight/rows;for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const c=document.createElement('canvas');c.width=Math.floor(w);c.height=Math.floor(h);c.getContext('2d').drawImage(im,x*w,y*h,w,h,0,0,c.width,c.height);out.push(c)}return out}
Promise.all([load('character-atlas.webp'),load('obstacle-atlas.webp'),load('terrain-atlas.webp'),load('props-atlas.webp'),load('background-atlas.webp'),load('side-floor.webp'),load('rat-sprite-strip.png')]).then(([soldier,obstacles,terrain,props,bg,floor,rat])=>{A.soldiers=cells(soldier,3,4);A.obstacles=cells(obstacles,2,2);A.terrain=cells(terrain,2,2);A.props=cells(props,3,2);A.bg=cells(bg,1,4);A.floor=floor;A.rat=rat;A.ready=true}).catch(err=>console.error('Trench artwork failed to load',err));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),time=()=>performance.now()/1000;
function img(c,i,x,y,w,h){if(i)c.drawImage(i,x,y,w,h)}
function sprite(c,im,sx,sy,sw,sh,x,y,w,h,flip=false){if(!im)return;c.save();if(flip){c.translate(x+w,y);c.scale(-1,1);c.drawImage(im,sx,sy,sw,sh,0,0,w,h)}else c.drawImage(im,sx,sy,sw,sh,x,y,w,h);c.restore()}
function tileParallax(c,im,y,h,factor,camera,alpha=1){if(!im)return;const w=h*im.width/im.height,off=(camera*factor)%(w*2);c.save();c.globalAlpha=alpha;for(let x=-off-w;x<960+w;x+=w*2){img(c,im,x,y,w,h);c.save();c.translate(x+2*w,y);c.scale(-1,1);img(c,im,0,0,w,h);c.restore()}c.restore()}
function background(e){const c=e.ctx,cam=e.camera.x;c.fillStyle='#68747b';c.fillRect(0,0,960,480);if(A.bg){img(c,A.bg[0],0,0,960,480);tileParallax(c,A.bg[1],75,176,.07,cam,.94);tileParallax(c,A.bg[2],125,205,.18,cam,.96);tileParallax(c,A.bg[3],165,235,.35,cam,.96)}
const veil=c.createLinearGradient(0,0,0,480);veil.addColorStop(0,'rgba(22,30,32,.04)');veil.addColorStop(.57,'rgba(27,30,29,.05)');veil.addColorStop(1,'rgba(18,17,15,.35)');c.fillStyle=veil;c.fillRect(0,0,960,480)}
function gapSurface(e,g){const c=e.ctx,wx=g.x+g.w/2;let top=480;for(const s of e.solids)if(s.source==='tile'&&wx>=s.x&&wx<s.x+s.w)top=Math.min(top,s.y);const x=g.x-e.camera.x;c.save();const hole=c.createLinearGradient(0,top,0,480);hole.addColorStop(0,'#171817');hole.addColorStop(.24,'#24201c');hole.addColorStop(1,'#111615');c.fillStyle=hole;c.fillRect(x,top, g.w,480-top);c.fillStyle='rgba(9,12,12,.8)';c.fillRect(x+5,top+18,g.w-10,480-top-18);c.fillStyle='#75553a';c.beginPath();c.moveTo(x-4,top-2);c.lineTo(x+10,top+8);c.lineTo(x+3,top+18);c.lineTo(x+18,top+22);c.lineTo(x+18,top-1);c.fill();c.beginPath();c.moveTo(x+g.w+4,top-2);c.lineTo(x+g.w-10,top+8);c.lineTo(x+g.w-3,top+17);c.lineTo(x+g.w-19,top+24);c.lineTo(x+g.w-18,top-1);c.fill();c.fillStyle='rgba(226,183,104,.85)';c.fillRect(x,top-2,g.w,2);c.fillRect(x,top-5,7,3);c.fillRect(x+g.w-8,top-5,8,3);c.restore()}
function terrain(e){const c=e.ctx,solids=e.solids,cell=32;
for(const o of solids){if(o.source!=='tile')continue;const x=Math.round(o.x-e.camera.x);if(x+cell<0||x>960)continue;c.fillStyle='#47372a';c.fillRect(x,o.y,cell,cell);c.fillStyle='rgba(17,18,16,.22)';c.fillRect(x,o.y,cell,cell);
const above=solids.some(a=>a.source==='tile'&&a.x===o.x&&a.y===o.y-cell);if(!above){c.fillStyle='#594633';c.fillRect(x,o.y,cell,10);c.fillStyle='#92704a';c.fillRect(x,o.y,cell,3);if(A.floor){const fx=(o.x*3)%A.floor.width; c.save();c.beginPath();c.rect(x,o.y-4,cell,18);c.clip();c.drawImage(A.floor,fx,0,Math.min(A.floor.width-fx,cell*3),A.floor.height,x,o.y-3,cell,18);c.restore()}else if(A.terrain)img(c,A.terrain[1],x,o.y-5,cell,20)}
if(A.terrain&&o.y>190){c.save();c.globalAlpha=.18;img(c,A.terrain[0],x,o.y,cell,cell);c.restore()}}
}
function platform(e,o){const c=e.ctx,x=Math.round(o.x-e.camera.x),id=String(o.platformId||'');if(x+o.w<0||x>960)return;
if(A.terrain){const tex=id.includes('sandbag')?A.terrain[3]:A.terrain[1];for(let px=0;px<o.w;px+=64)img(c,tex,x+px,o.y-12,Math.min(72,o.w-px),25)}
c.fillStyle=id.includes('sandbag')?'rgba(116,88,54,.9)':'rgba(86,61,39,.9)';c.fillRect(x,o.y+2,o.w,Math.max(4,o.h-2));c.fillStyle='#c19a5d';c.fillRect(x,o.y,o.w,3);c.strokeStyle='rgba(38,31,23,.75)';c.lineWidth=1;for(let k=12;k<o.w;k+=23){c.beginPath();c.moveTo(x+k,o.y+4);c.lineTo(x+k,o.y+o.h);c.stroke()}
if(id.includes('sandbag')){c.fillStyle='#a58b63';for(let px=12;px<o.w;px+=33){c.beginPath();c.ellipse(x+px,o.y+1,15,6,0,0,Math.PI*2);c.fill();c.strokeStyle='rgba(45,37,28,.55)';c.stroke()}}
}
function hazard(e,o){if(!o.active)return;const c=e.ctx,x=o.x-e.camera.x,y=o.y,w=o.w,h=o.h;if(x+w<0||x>960)return;const cx=x+w/2,glow=c.createRadialGradient(cx,y+h*.5,2,cx,y+h*.5,42);glow.addColorStop(0,'rgba(233,183,91,.34)');glow.addColorStop(.5,'rgba(226,171,70,.16)');glow.addColorStop(1,'rgba(226,171,70,0)');c.fillStyle=glow;c.fillRect(cx-42,y-16,84,h+32);c.save();c.shadowColor='#e8bd71';c.shadowBlur=11;if(A.obstacles)img(c,A.obstacles[1],x-11,y-8,w+22,h+13);else{c.strokeStyle='#bca274';c.lineWidth=3;c.beginPath();c.moveTo(x,y+h);c.lineTo(x+w,y);c.stroke()}c.restore();c.fillStyle='#efd492';c.font='900 11px system-ui';c.textAlign='center';c.fillText('WIRE',cx,y-12)}
function checkpoint(e,o){if(!o.active)return;const c=e.ctx,x=o.x-e.camera.x,y=o.y;if(x<-70||x>990)return;c.save();c.shadowColor='#e7bc69';c.shadowBlur=16;if(A.terrain)img(c,A.terrain[2],x-8,y-44,50,54);else{c.strokeStyle='#dab876';c.lineWidth=3;c.strokeRect(x,y-35,34,35)}c.restore();c.fillStyle='#f3d489';c.font='900 9px system-ui';c.textAlign='center';c.fillText('RALLY',x+16,y-46)}
function gate(e,g){if(!g.active)return;const c=e.ctx,x=g.x-e.camera.x;if(x<-40||x>1000)return;c.fillStyle='rgba(27,27,24,.92)';c.fillRect(x,g.y,g.w,g.h);c.fillStyle='#775b3d';c.fillRect(x-10,g.h-60,g.w+20,12);c.fillStyle='#96764b';c.fillRect(x-6,g.h-57,g.w+12,4);c.strokeStyle='rgba(204,176,119,.8)';c.lineWidth=3;c.strokeRect(x-7,Math.max(130,g.h-156),g.w+14,156);c.fillStyle='#dfbe77';c.font='900 8px system-ui';c.textAlign='center';c.fillText('ORDERS',x+g.w/2,Math.max(126,g.h-164))}
function station(e,q){if(!q.active)return;const c=e.ctx,x=q.x-e.camera.x,y=q.visualY??q.y;if(x<-70||x>1010)return;const colors={orders:'#e6c177',radio:'#9fb18e',map:'#d8ca9f',intel:'#dcaa65'},col=colors[q.stationType]||'#d8ca9f';c.save();c.shadowColor=col;c.shadowBlur=12;c.fillStyle='#3a3228';c.fillRect(x+3,y+29,34,19);c.fillStyle='#b89b68';c.fillRect(x+1,y+27,38,4);c.fillStyle='#e6ddc6';c.fillRect(x+7,y+4,25,27);c.strokeStyle='#655440';c.lineWidth=2;c.strokeRect(x+7,y+4,25,27);c.fillStyle=col;c.font='900 17px Georgia';c.textAlign='center';c.fillText('?',x+19.5,y+24);c.restore();c.fillStyle='#f0d998';c.font='900 8px system-ui';c.textAlign='center';c.fillText('FIELD CHECK',x+20,y-3)}
function collectible(e,o){if(!o.active)return;const c=e.ctx,x=o.x-e.camera.x,y=o.y+Math.sin(time()*3+o.x)*3;if(x<-36||x>996)return;c.save();c.shadowColor='#f2cf7e';c.shadowBlur=15;c.fillStyle='#e4c781';c.beginPath();c.roundRect(x,y,22,22,4);c.fill();c.fillStyle='#59604c';c.fillRect(x+4,y+5,14,2);c.fillRect(x+4,y+10,11,2);c.fillRect(x+4,y+15,13,2);c.restore()}
function mover(e,m){if(!m.active||m.phase==='reset')return;const c=e.ctx,x=m.x-e.camera.x,y=m.y;if(x<-100||x>1060)return;if(m.type==='rat'&&A.rat){const fw=A.rat.naturalWidth/2,fh=A.rat.naturalHeight,frame=Math.floor(time()*7)%2;const sourceY=Math.round(fh*.34),sourceH=Math.round(fh*.38);c.save();c.shadowColor='rgba(246,192,106,.75)';c.shadowBlur=9;sprite(c,A.rat,frame*fw,sourceY,fw,sourceH,x-17,y-13,65,34,m.dir<0);c.restore()}else{c.save();const cx=x+m.w/2,cy=y+m.h/2;c.shadowColor='#f0a659';c.shadowBlur=m.phase==='falling'?22:12;c.fillStyle='#332e29';c.beginPath();c.arc(cx,cy,14,0,Math.PI*2);c.fill();c.fillStyle='#dfad63';c.beginPath();c.arc(cx-3,cy-4,6,0,Math.PI*2);c.fill();c.strokeStyle='rgba(241,206,144,.84)';c.lineWidth=2;c.beginPath();c.moveTo(cx,y-8);c.lineTo(cx,y-26);c.stroke();if(m.phase==='falling'){c.fillStyle='rgba(245,181,92,.72)';c.beginPath();c.moveTo(cx,y+28);c.lineTo(cx-6,y+16);c.lineTo(cx+6,y+16);c.fill()}c.restore()}}
function finish(e){const c=e.ctx,o=e.level.finish,x=o.x-e.camera.x,y=o.y;if(x<-240||x>1000)return;c.save();c.fillStyle='#46392b';c.fillRect(x,y+25,o.w-2,o.h-25);if(A.terrain)img(c,A.terrain[3],x-12,y+4,o.w+22,38);c.fillStyle='#171a19';c.fillRect(x+12,y+52,o.w-26,o.h-52);c.fillStyle='#d7bd7f';c.font='900 9px system-ui';c.textAlign='center';c.fillText('COMMAND POST',x+o.w/2,y+47);c.restore()}
function soldier(e){const c=e.ctx,p=e.player,frames=A.soldiers;if(!frames)return;const run=p.grounded&&Math.abs(p.vx)>48,frame=!p.grounded?(p.vy<0?7:9):(run?1+Math.floor(time()*8)%6:0),im=frames[frame]||frames[0],ratio=im.width/im.height,h=82,w=Math.max(50,h*ratio),x=p.x-e.camera.x+p.w/2-w/2,y=p.y+p.h-h+7;c.save();c.fillStyle='rgba(11,11,10,.4)';c.beginPath();c.ellipse(p.x-e.camera.x+p.w/2,p.y+p.h+2,20,4,0,0,Math.PI*2);c.fill();if(p.vx<0){c.translate(x+w,y);c.scale(-1,1);c.drawImage(im,0,0,w,h)}else c.drawImage(im,x,y,w,h);c.restore()}
TA.render=e=>{const c=e.ctx,cam=e.camera.x;background(e);for(const g of e.level.gaps||[])gapSurface(e,g);terrain(e);
for(const o of e.solids){if(o.source==='tile'||o.source==='gate')continue;if(o.source==='platform'||o.source==='movingPlatform')platform(e,o)}
e.hazards.forEach(o=>hazard(e,o));e.checkpoints.forEach(o=>checkpoint(e,o));e.gates.forEach(g=>gate(e,g));e.questionTriggers.forEach(q=>station(e,q));e.collectibles.forEach(o=>collectible(e,o));e.movers.forEach(m=>mover(e,m));finish(e);soldier(e);
if(e.debugLevel&&e.visualValidation?.issues?.length){c.font='800 10px system-ui';e.visualValidation.issues.forEach(i=>{const x=i.x-cam;if(x+i.w<0||x>960)return;c.strokeStyle=i.severity==='error'?'#ef4444':'#f59e0b';c.lineWidth=3;c.strokeRect(x,i.y,i.w,i.h)})}
const pf=document.getElementById('progress-fill');if(pf)pf.style.width=Math.max(2,Math.min(100,e.player.x/e.level.finish.x*100))+'%';
if(e.state==='won'){c.fillStyle='rgba(14,18,17,.55)';c.fillRect(0,0,960,480);c.fillStyle='#f4e9d1';c.font='700 34px Georgia';c.textAlign='center';c.fillText('RUN COMPLETE',480,238);c.font='700 17px system-ui';c.fillText('The intelligence has reached the command post.',480,272)}
};
})();